//  Official, authentic AI provider & agent brand icons rendered cleanly and formally.
//

import SwiftUI
import AppKit

struct AIProviderBrandIcon: View {
    let provider: String
    var size: CGFloat = 20
    var isSelected: Bool = false
    
    var body: some View {
        Group {
            if let nsImage = Self.image(for: provider) {
                Image(nsImage: nsImage)
                    .resizable()
                    .aspectRatio(contentMode: .fit)
                    .frame(width: size, height: size)
            } else {
                fallbackIcon
            }
        }
    }
    
    @ViewBuilder
    private var fallbackIcon: some View {
        Image(systemName: "cpu")
            .font(.system(size: size * 0.7))
            .foregroundColor(.white.opacity(0.6))
            .frame(width: size, height: size)
    }
    
    private static var iconCache: [String: NSImage] = [:]
    
    static func image(for provider: String) -> NSImage? {
        let rawKey = provider.lowercased().replacingOccurrences(of: "-", with: "_")
        let resolvedKey: String
        switch rawKey {
        case "claude", "claudecode", "claude_code", "anthropic":
            resolvedKey = "anthropic"
        case "codex", "codexengine", "codex_engine", "openai":
            resolvedKey = "openai"
        case "agy", "antigravity", "gemini":
            resolvedKey = "gemini"
        case "cursor", "cursoragent", "cursor_agent":
            resolvedKey = "cursor"
        case "copilot", "githubcopilot", "github_copilot", "github":
            resolvedKey = "copilot"
        case "microcode", "microcodenative", "microcode_native":
            resolvedKey = "microcode"
        case "aider":
            resolvedKey = "aider"
        case "opencode":
            resolvedKey = "opencode"
        case "zed", "zedengine", "zed_engine", "zcode":
            resolvedKey = "zed"
        case "free_model", "freemodel":
            resolvedKey = "local"
        default:
            resolvedKey = rawKey
        }
        
        if let cached = iconCache[resolvedKey] {
            return cached
        }
        guard let base64 = base64Data[resolvedKey],
              let data = Data(base64Encoded: base64),
              let img = NSImage(data: data) else {
            return nil
        }
        iconCache[resolvedKey] = img
        return img
    }
    
    private static let base64Data: [String: String] = [
        "aider": "",
        "anthropic": "",
        "copilot": "",
        "cursor": "",
        "deepseek": "",
        "gemini": "",
        "glm": "",
        "grok": "",
        "local": "",
        "microcode": "",
        "omni": "",
        "openai": "",
        "opencode": "",
        "qwen": "",
        "zed": "",
    ]
}
